<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker','doctor']);$con->query("CREATE TABLE IF NOT EXISTS emergency_cases(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,priority VARCHAR(30) DEFAULT 'Normal',chief_complaint VARCHAR(255) DEFAULT '',doctor_id INT DEFAULT 0,treatment TEXT,status VARCHAR(30) DEFAULT 'Open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status),INDEX(priority)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$con->prepare("INSERT INTO emergency_cases(patient_id,priority,chief_complaint,doctor_id) VALUES(?,?,?,?)");$p=(int)$_POST['patient_id'];$pr=$_POST['priority'];$c=trim($_POST['chief_complaint']);$d=(int)($_POST['doctor_id']??0);$s->bind_param('issi',$p,$pr,$c,$d);if($s->execute())$msg='Emergency case registered.';}$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$rows=$con->query("SELECT e.*,p.patientname,COALESCE(d.doctorname,'') doctorname FROM emergency_cases e JOIN patient p ON p.patientid=e.patient_id LEFT JOIN doctor d ON d.doctorid=e.doctor_id ORDER BY e.id DESC LIMIT 100");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Emergency</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">EMERGENCY</span><h1>Emergency & Triage</h1><p>Register emergencies, set priority, assign doctors and track treatment.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>Emergency registration</h2><form method="post" class="form-grid"><label>Patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>"><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><label>Priority<select name="priority"><option>Critical</option><option>Urgent</option><option selected>Normal</option></select></label><label>Doctor ID<input type="number" name="doctor_id" min="0"></label><label>Chief complaint<textarea name="chief_complaint"></textarea></label><button class="primary-btn">Register emergency</button></form></div><div class="panel"><h2>Emergency queue</h2><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Priority</th><th>Complaint</th><th>Doctor</th><th>Status</th><th>Time</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['patientname'])?></td><td><?=esc($r['priority'])?></td><td><?=esc($r['chief_complaint'])?></td><td><?=esc($r['doctorname'])?></td><td><?=esc($r['status'])?></td><td><?=esc($r['created_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
